CREATE TABLE project (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE boq_items (ref TEXT PRIMARY KEY, package TEXT, grp TEXT, phase TEXT, lead_class TEXT, value_sar INTEGER, descriptor TEXT, scope_description TEXT);
CREATE TABLE phases (phase TEXT, stage TEXT, start_month INTEGER, finish_month INTEGER, start_date_indicative TEXT, finish_date_indicative TEXT);
CREATE TABLE milestones (id TEXT PRIMARY KEY, name TEXT, month_from_ntp INTEGER, basis TEXT, note TEXT);
CREATE TABLE cash_flow_quarterly (period TEXT, month_from INTEGER, month_to INTEGER, progress_value_sar_m REAL, net_cash_sar_m REAL, cumulative_net_cash_pct REAL);
CREATE TABLE cash_flow_semiannual (period TEXT, month_from INTEGER, month_to INTEGER, progress_value_sar_m REAL, net_cash_sar_m REAL, cumulative_net_cash_pct REAL);
CREATE TABLE cost_components (component TEXT, sar REAL);
CREATE TABLE tga_requirements (requirement TEXT, contract_wording TEXT, programme_meaning TEXT, clause TEXT);
CREATE TABLE authorities (entity TEXT, approves_or_reviews TEXT, stage TEXT, contractor_documents TEXT, source TEXT);
CREATE TABLE approval_durations (activity TEXT, days TEXT, owner TEXT, basis TEXT);
CREATE TABLE documents_by_stage (stage TEXT, documents TEXT, approved_by TEXT);
CREATE TABLE design_gates (gate TEXT, sar_stage TEXT, completion TEXT, month INTEGER, review_days INTEGER, content TEXT);
CREATE TABLE project_status (item TEXT, status TEXT, detail TEXT);
CREATE TABLE open_points (point TEXT, owner TEXT);
CREATE TABLE tga_process_activities_draft (activity_id TEXT PRIMARY KEY, name TEXT, duration_days INTEGER, predecessors TEXT, basis TEXT, note TEXT);
CREATE TABLE deliverables (file TEXT, description TEXT, status TEXT);
CREATE VIEW v_long_lead AS SELECT ref, package, phase, value_sar FROM boq_items WHERE lead_class = 'Long';
CREATE VIEW v_value_by_group AS SELECT grp, COUNT(*) AS items, SUM(value_sar) AS value_sar FROM boq_items GROUP BY grp;
CREATE VIEW v_value_by_phase AS SELECT phase, COUNT(*) AS items, SUM(value_sar) AS value_sar FROM boq_items GROUP BY phase;
CREATE TABLE bl02_activities (activity_id TEXT PRIMARY KEY, name TEXT, type TEXT, duration_days INTEGER, early_start TEXT, early_finish TEXT, late_start TEXT, late_finish TEXT,
  total_float_days INTEGER, responsible TEXT, tga_process TEXT, submit_review TEXT, duration_basis TEXT, is_new_in_bl02 INTEGER, on_critical_path INTEGER);
CREATE TABLE bl02_relationships (predecessor TEXT, successor TEXT, type TEXT, lag_days INTEGER);
CREATE TABLE bl02_critical_path (seq INTEGER, activity_id TEXT, name TEXT, duration_days INTEGER, early_start TEXT, early_finish TEXT, total_float_days INTEGER);
CREATE VIEW v_bl02_near_critical_tga AS SELECT activity_id, name, early_finish, total_float_days, responsible FROM bl02_activities WHERE is_new_in_bl02 = 1 AND type != 'TT_LOE' AND total_float_days <= 30 ORDER BY total_float_days;